package harness

import (
	"context"
	"loreviva.local/loreviva/internal/domain"
	"loreviva.local/loreviva/internal/maintenance"
	"sync"
	"sync/atomic"
)

func validMockUsage(m domain.MockUsageMeasurement) bool {
	return m.Identity.Validate() == nil && m.Provider == "r0-mock" && m.Account == "r0-mock-supplier" && m.InputUnits > 0 && m.InputUnits <= 16000 && m.OutputUnits > 0 && m.OutputUnits <= 4000
}

// Only Generate supplies these actual rune counts while it owns the canonical
// request and generated bytes. Later accounting never rereads either body.
func (j *MockJournal) observeUsage(ctx context.Context, id domain.MockRequestIdentity, in, out uint64) error {
	m := domain.MockUsageMeasurement{Identity: id, Provider: "r0-mock", Account: "r0-mock-supplier", InputUnits: in, OutputUnits: out}
	if !validMockUsage(m) {
		return ErrMockContinuity
	}
	ctx, release, e := j.participant.Enter(ctx, maintenance.MockWriter)
	if e != nil {
		return e
	}
	defer release()
	done, e := j.root.Lock(ctx, "state.lock")
	if e != nil {
		return e
	}
	defer done()
	a, entries, e := j.load(ctx)
	if e != nil {
		return e
	}
	complete := false
	for _, entry := range entries {
		if entry.Result.Identity != id {
			continue
		}
		if entry.Usage != nil {
			return ErrMockContinuity
		}
		if entry.Result.State == "SUCCEEDED" && !entry.Result.UsageKnown {
			complete = true
		}
	}
	if !complete {
		return ErrMockContinuity
	}
	return j.appendEntry(ctx, a, mockEntry{Result: domain.MockResultMetadata{Identity: id, State: "USAGE_OBSERVED"}, Usage: &m})
}

func (j *MockJournal) publishObservedUsage(ctx context.Context, id domain.MockRequestIdentity) error {
	ctx, release, e := j.participant.Enter(ctx, maintenance.MockWriter)
	if e != nil {
		return e
	}
	defer release()
	done, e := j.root.Lock(ctx, "state.lock")
	if e != nil {
		return e
	}
	defer done()
	a, entries, e := j.load(ctx)
	if e != nil {
		return e
	}
	var m *domain.MockUsageMeasurement
	for _, entry := range entries {
		if entry.Result.Identity != id || entry.Usage == nil {
			continue
		}
		if entry.Result.State == "USAGE_PUBLISHED" {
			return nil
		}
		copy := *entry.Usage
		m = &copy
	}
	if m == nil {
		return ErrMockContinuity
	}
	return j.appendEntry(ctx, a, mockEntry{Result: domain.MockResultMetadata{Identity: id, State: "USAGE_PUBLISHED"}, Usage: m})
}

type originalUsageEvidence struct {
	owner       *MockJournal
	continuity  *maintenance.SettlementContinuity
	measurement domain.MockUsageMeasurement
	head        domain.MockHead
	closed      atomic.Bool
	once        sync.Once
	close       func()
}

func (e *originalUsageEvidence) Measurement() domain.MockUsageMeasurement { return e.measurement }
func (e *originalUsageEvidence) Head() domain.MockHead                    { return e.head }
func (e *originalUsageEvidence) Close()                                   { e.once.Do(func() { e.closed.Store(true); e.close() }) }

func (j *MockJournal) ReadOriginalUsageEvidence(ctx context.Context, id domain.MockRequestIdentity) (domain.OriginalUsageEvidence, error) {
	ctx, release, e := j.participant.Enter(ctx, maintenance.DeadlineWriter)
	if e != nil {
		return nil, e
	}
	done, e := j.root.Lock(ctx, "state.lock")
	if e != nil {
		release()
		return nil, e
	}
	close := func() { done(); release() }
	a, entries, e := j.load(ctx)
	if e != nil {
		close()
		return nil, e
	}
	var m *domain.MockUsageMeasurement
	for _, entry := range entries {
		if entry.Usage == nil || entry.Result.Identity.AttemptID != id.AttemptID || entry.Result.State != "USAGE_PUBLISHED" {
			continue
		}
		if entry.Result.Identity != id {
			close()
			return nil, ErrMockContinuity
		}
		copy := *entry.Usage
		m = &copy
	}
	if m == nil {
		close()
		return nil, ErrMockContinuity
	}
	continuity, e := j.participant.HoldSettlementContinuity(ctx, j.binding, a.Head)
	if e != nil {
		close()
		return nil, e
	}
	return &originalUsageEvidence{owner: j, continuity: continuity, measurement: *m, head: a.Head, close: func() { continuity.Close(); close() }}, nil
}
func (j *MockJournal) CheckOriginalUsageEvidence(proof domain.OriginalUsageEvidence, id domain.SettlementServiceIdentity) error {
	actual, ok := proof.(*originalUsageEvidence)
	if !ok || actual.owner != j || actual.closed.Load() {
		return ErrMockContinuity
	}
	return actual.continuity.Check(id, actual.head)
}
